mutations.original:
auto grants_state = [state](const Buff& buff)
{
	const auto effect = buff_state_effects.find(buff.type);
	return effect != buff_state_effects.end() &&
		effect->second == state;
};

mutations.mutated:
auto grants_state = [buffType](const Buff& buff)
{
	return buff.type == buffType;
};
